class CustomSet:
    def __init__(self, elements=[]):
        # Use a private list to store unique elements.
        # Avoid sharing the default list by always creating a new list.
        self._elements = []
        try:
            for e in elements:
                if e not in self._elements:
                    self._elements.append(e)
        except TypeError:
            # If elements is not iterable (unlikely in tests), ignore.
            pass

    def isempty(self):
        return len(self._elements) == 0

    def __contains__(self, element):
        return element in self._elements

    def _as_iterable(self, other):
        # Helper: return a list of elements from other CustomSet or any iterable.
        if isinstance(other, CustomSet):
            return other._elements
        try:
            return list(other)
        except TypeError:
            # If not iterable, treat as empty
            return []

    def issubset(self, other):
        other_elements = self._as_iterable(other)
        for e in self._elements:
            if e not in other_elements:
                return False
        return True

    def isdisjoint(self, other):
        other_elements = self._as_iterable(other)
        for e in self._elements:
            if e in other_elements:
                return False
        return True

    def __eq__(self, other):
        if not isinstance(other, CustomSet):
            # If other is an iterable, consider equality of elements as sets.
            try:
                other = CustomSet(other)
            except TypeError:
                return False
        # Equal if both are subsets of each other (and therefore same elements)
        return self.issubset(other) and other.issubset(self)

    def add(self, element):
        if element not in self._elements:
            self._elements.append(element)

    def intersection(self, other):
        other_elements = self._as_iterable(other)
        return CustomSet([e for e in self._elements if e in other_elements])

    def __sub__(self, other):
        other_elements = self._as_iterable(other)
        return CustomSet([e for e in self._elements if e not in other_elements])

    def __add__(self, other):
        other_elements = self._as_iterable(other)
        result = CustomSet(self._elements)
        for e in other_elements:
            if e not in result._elements:
                result._elements.append(e)
        return result
